mapper.select:
SELECT id, user_id, identity_type, issuer, identifier, normalized_identifier, status,
       verified_at, last_used_at, created_at, updated_at
  FROM user_identity WHERE id = #{id}

mapper.update:
UPDATE user_account SET security_version = security_version + 1, updated_at = CURRENT_TIMESTAMP
, email = #{email}
 WHERE id = #{id} AND deleted_at IS NULL
